import { existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { acquireDatabaseLifecycleLock, releaseDatabaseLifecycleLock } from "../persistence/DatabaseLifecycleLock.ts";

export const resolveProductDatabasePath = (stateDir: string) => join(stateDir, "stores", "product.sqlite");

export async function makeProductControlPlaneLayer(stateDir: string) {
  const databasePath = resolveProductDatabasePath(stateDir);
  if (existsSync("product-state-v1.sqlite") || existsSync("product-state-v1.sqlite-wal") || existsSync("product-state-v1.sqlite-shm")) {
    throw new Error("PREBASELINE_RESET_REQUIRED");
  }
  mkdirSync(dirname(databasePath), { recursive: true });
  const lock = await acquireDatabaseLifecycleLock(databasePath);
  try {
    if (existsSync("product-state-v1.sqlite") || existsSync("product-state-v1.sqlite-wal") || existsSync("product-state-v1.sqlite-shm")) {
      throw new Error("PREBASELINE_RESET_REQUIRED");
    }
    const database = new DatabaseSync(databasePath);
    database.exec("CREATE TABLE product_meta(schema_generation INTEGER)");
    database.close();
  } finally {
    await releaseDatabaseLifecycleLock(lock);
  }
}
